def maxRemovable(n, edges):
    def make():
        return list(range(n + 1))

    def find(p, x):
        while p[x] != x:
            p[x] = p[p[x]]
            x = p[x]
        return x

    alice, bob = make(), make()
    ga = gb = n
    kept = 0
    for t, a, b in edges:
        if t != 3:
            continue
        ra, rb = find(alice, a), find(alice, b)
        if ra != rb:
            alice[ra] = rb
            ga -= 1
            xa, xb = find(bob, a), find(bob, b)
            bob[xa] = xb
            gb -= 1
            kept += 1
    for t, a, b in edges:
        if t == 1:
            ra, rb = find(alice, a), find(alice, b)
            if ra != rb:
                alice[ra] = rb
                ga -= 1
                kept += 1
        elif t == 2:
            ra, rb = find(bob, a), find(bob, b)
            if ra != rb:
                bob[ra] = rb
                gb -= 1
                kept += 1
    if ga != 1 or gb != 1:
        return -1
    return len(edges) - kept
